@startuml

class Customer {
  + name : string
  + accountDetails : string
}

class Broker {
  + name : string
}

class InsuranceProduct {
  + name : string
  + price : float
}

class Offer {
  + date : date
  + details : string
}

class Contract {
  + signingDate : date
  + billingFrequency : string
}

class Invoice {
  + amount : float
  + date : date
}

class ClaimCase {
  + caseId : int
  + status : string
}

class Estimator {
  + name : string
  + expertise : string
}

class EstimatorReport {
  + reportDate : date
  + findings : string
}

class Compensation {
  + amount : float
  + paymentDate : date
}

Broker "1" -- "0..*" Customer : manages
Customer "1" -- "0..*" Offer : receives
Customer "1" -- "0..*" Contract : signs
Customer "1" -- "0..*" ClaimCase : files
Customer "1" -- "1" Compensation : receives

Contract "1" -- "1" InsuranceProduct : based on
Contract "1" -- "0..*" Invoice : generates

ClaimCase "1" *-- "1..*" EstimatorReport : contains
ClaimCase "1" -- "0..*" Estimator : assessed by
Estimator "1" -- "0..*" EstimatorReport : issues
ClaimCase "1" -- "0..1" Compensation : results in

@enduml

